import{_ as e,o,c as r,a2 as t}from"./chunks/framework.DA69LXMH.js";const p=JSON.parse('{"title":"Voz & Transcrição (STT / TTS)","description":"","frontmatter":{},"headers":[],"relativePath":"recursos/voz-e-stt.md","filePath":"recursos/voz-e-stt.md"}'),i={name:"recursos/voz-e-stt.md"};function s(d,a,n,c,l,m){return o(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="voz-transcricao-stt-tts" tabindex="-1">Voz &amp; Transcrição (STT / TTS) <a class="header-anchor" href="#voz-transcricao-stt-tts" aria-label="Permalink to &quot;Voz &amp; Transcrição (STT / TTS)&quot;">​</a></h1><p>O núcleo do <strong>EchoBot</strong> combina modelos modernos de inteligência artificial acústica e síntese neural para processar o áudio da sua mesa com velocidade extrema e fidelidade dramática.</p><hr><h2 id="🎧-transcricao-de-fala-para-texto-speech-to-text" tabindex="-1">🎧 Transcrição de Fala para Texto (Speech-to-Text) <a class="header-anchor" href="#🎧-transcricao-de-fala-para-texto-speech-to-text" aria-label="Permalink to &quot;🎧 Transcrição de Fala para Texto (Speech-to-Text)&quot;">​</a></h2><h3 id="faster-whisper-com-modelo-large-v3-turbo" tabindex="-1">Faster-Whisper com Modelo Large-v3-Turbo <a class="header-anchor" href="#faster-whisper-com-modelo-large-v3-turbo" aria-label="Permalink to &quot;Faster-Whisper com Modelo Large-v3-Turbo&quot;">​</a></h3><p>O sistema utiliza a arquitetura otimizada <strong>Faster-Whisper (CTranslate2)</strong>:</p><ul><li><strong>Modelo Padrão <code>large-v3-turbo</code>:</strong> Reduz o número de camadas do decodificador de 32 para 4, proporcionando uma aceleração de <strong>4x a 6x em relação ao Whisper tradicional</strong>, mantendo a alta acurácia do modelo Large. Uma sessão inteira de 3 horas é processada em poucos minutos.</li><li><strong>Modelos Alternativos:</strong> Seleção via interface entre os modelos <code>tiny</code>, <code>base</code>, <code>small</code>, <code>medium</code> e <code>large-v3-turbo</code>.</li><li><strong>Aceleração por Hardware NVIDIA CUDA:</strong> Inferência direta em GPU com quantização <code>int8_float16</code>, compatível com placas GeForce GTX 1660 e linhas RTX 20/30/40.</li><li><strong>Fallback Automático para CPU:</strong> Em máquinas sem placa de vídeo NVIDIA, o sistema aciona automaticamente a versão compilada em C++ do <strong><code>whisper.cpp</code></strong> ou modo multi-thread de CPU.</li></ul><h3 id="arquitetura-desacoplada-sidecar-pattern" tabindex="-1">Arquitetura Desacoplada (Sidecar Pattern) <a class="header-anchor" href="#arquitetura-desacoplada-sidecar-pattern" aria-label="Permalink to &quot;Arquitetura Desacoplada (Sidecar Pattern)&quot;">​</a></h3><p>O processamento pesado de áudio não trava a interface web:</p><ul><li>O motor de IA é executado em um processo servidor FastAPI independente na porta <code>8001</code>.</li><li>Isso impede vazamentos de memória, mantém o instalador desktop principal ultraleve (&lt;60MB) e baixa os modelos de IA sob demanda com feedback visual de progresso.</li></ul><h3 id="identificacao-biometrica-de-vozes-speaker-id" tabindex="-1">Identificação Biométrica de Vozes (Speaker ID) <a class="header-anchor" href="#identificacao-biometrica-de-vozes-speaker-id" aria-label="Permalink to &quot;Identificação Biométrica de Vozes (Speaker ID)&quot;">​</a></h3><ul><li><strong>Reconhecimento por Padrão Vocal:</strong> Utilizando o modelo acústico <code>UniSpeech-SAT</code> e inferência em lote com fatiamento em memória via NumPy, o sistema analisa as frequências vocais de cada participante.</li><li><strong>Associação Automática:</strong> As falas são atribuídas aos personagens cadastrados na campanha sem depender exclusivamente do Discord.</li></ul><h3 id="filtro-inteligente-ic-in-character-vs-ooc-out-of-character" tabindex="-1">Filtro Inteligente IC (In-Character) vs OOC (Out-of-Character) <a class="header-anchor" href="#filtro-inteligente-ic-in-character-vs-ooc-out-of-character" aria-label="Permalink to &quot;Filtro Inteligente IC (In-Character) vs OOC (Out-of-Character)&quot;">​</a></h3><ul><li>Durante a partida, jogadores alternam entre falas na narrativa (<em>&quot;Eu conjuro um míssil mágico contra o monstro&quot;</em>) e conversas fora do personagem (<em>&quot;Alguém quer pedir pizza?&quot;</em>).</li><li>O EchoBot classifica automaticamente cada fala e permite ao Mestre alternar o status através de botões rápidos na transcrição, garantindo que conversas paralelas não poluam a crônica épica.</li><li>Suporte a deleção individual ou em lote (<em>bulk delete</em>) de trechos indesejados.</li></ul><hr><h2 id="🗣️-sintese-de-voz-text-to-speech-narracao-de-npcs" tabindex="-1">🗣️ Síntese de Voz (Text-to-Speech) &amp; Narração de NPCs <a class="header-anchor" href="#🗣️-sintese-de-voz-text-to-speech-narracao-de-npcs" aria-label="Permalink to &quot;🗣️ Síntese de Voz (Text-to-Speech) &amp; Narração de NPCs&quot;">​</a></h2><h3 id="kokoro-tts-v1-0-local-gratuito" tabindex="-1">Kokoro TTS v1.0 (Local &amp; Gratuito) <a class="header-anchor" href="#kokoro-tts-v1-0-local-gratuito" aria-label="Permalink to &quot;Kokoro TTS v1.0 (Local &amp; Gratuito)&quot;">​</a></h3><p>Dê voz aos seus NPCs e aos resumos da sessão sem pagar assinaturas de terceiros:</p><ul><li><strong>Execução 100% Offline:</strong> Modelo ONNX executado nativamente em Python, com baixíssimo consumo de CPU e RAM.</li><li><strong>Qualidade de Estúdio:</strong> Vozes expressivas e naturais com ritmo dramático, adequadas para a narração de crônicas de fantasia.</li><li><strong>Zero Custo de API:</strong> Narre resumos ilimitados sem depender de internet ou créditos pagos.</li></ul><h3 id="provedores-em-nuvem-de-alta-fidelidade" tabindex="-1">Provedores em Nuvem de Alta Fidelidade <a class="header-anchor" href="#provedores-em-nuvem-de-alta-fidelidade" aria-label="Permalink to &quot;Provedores em Nuvem de Alta Fidelidade&quot;">​</a></h3><p>Para mestres que buscam clonagem de voz ou timbres específicos:</p><ul><li><strong>ElevenLabs:</strong> Suporte a vozes personalizadas com modulação de estabilidade e clareza.</li><li><strong>Deepgram Aura:</strong> Síntese em tempo real de altíssima velocidade.</li></ul><hr><h2 id="🎵-mixagem-com-trilha-sonora-autonoma" tabindex="-1">🎵 Mixagem com Trilha Sonora Autônoma <a class="header-anchor" href="#🎵-mixagem-com-trilha-sonora-autonoma" aria-label="Permalink to &quot;🎵 Mixagem com Trilha Sonora Autônoma&quot;">​</a></h2><p>O EchoBot inclui um estúdio de mixagem automática de áudio:</p><ul><li><strong>Biblioteca Embutida Royalty-Free:</strong> Seleção de trilhas instrumentais e ambientes imersivos curados para fantasia e RPG.</li><li><strong>Duck / Mixer Dinâmico:</strong> O volume da música de fundo é suavizado automaticamente quando a voz do narrador está falando.</li><li><strong>Download Duplo:</strong> Na tela de revisão do roteiro, você pode baixar tanto o <strong>áudio final mixado</strong> quanto o <strong>Stem isolado</strong> (apenas a voz limpa sem música de fundo, ideal para edição no Audacity ou software de podcast).</li></ul>',26)])])}const h=e(i,[["render",s]]);export{p as __pageData,h as default};
